// Group emailless leads by company so we spend one OSINT job per employer, not per person.

const MAX_COMPANIES_PER_RUN = 15;
const ne = (v) => v !== undefined && v !== null && String(v).trim() !== '';

// A 'company' made only of job words is a job title, not an employer.
// This is what produced leader.com / programdirector.org in v1 - never build a
// domain from it.
const ROLE_WORDS = new Set(['director','directors','leader','leaders','leadership','manager','management','executive','officer','president','founder','cofounder','ceo','coo','cfo','cto','chair','chairman','board','consultant','consulting','strategist','specialist','coordinator','administrator','administration','program','programs','development','fundraising','fundraiser','grant','grants','writer','writing','nonprofit','non','profit','volunteer','entrepreneur','inventor','professional','freelance','independent','self','employed','retired','advisor','adviser','principal','owner','partner','associate','analyst','engineer','designer','marketing','sales','operations','recruiter','student','intern','philanthropy','philanthropist','relations','affairs','outreach','engagement','strategy','strategic','various','none']);
const STOPWORDS = new Set(['the','of','for','and','a','an','at','in','on','to','inc','llc','ltd','corp','corporation','co','company','group','holdings','plc','org']);
const isJobTitle = (nameStr) => {
  const toks = String(nameStr || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
  if (!toks.length) return true;
  return toks.filter(t => !STOPWORDS.has(t) && !ROLE_WORDS.has(t)).length === 0;
};

const rows = $input.all().map(i => i.json);

const knownEmails = new Set(
  rows.filter(r => ne(r.email)).map(r => String(r.email).trim().toLowerCase())
);

const groups = new Map();

for (const r of rows) {
  if (ne(r.email)) continue;
  if (!ne(r.provider_id)) continue;
  if (String(r.email_send_status || '').toLowerCase() === 'unsubscribed') continue;

  const company = ne(r.company_name) ? String(r.company_name).trim() : '';
  const domain = ne(r.company_domain) ? String(r.company_domain).trim().toLowerCase() : '';

  if (!company && !domain) continue;
  if (company && isJobTitle(company)) continue;

  const key = (domain || company).toLowerCase();
  if (!groups.has(key)) groups.set(key, { company, domain, members: [] });
  const g = groups.get(key);
  if (!g.company && company) g.company = company;
  if (!g.domain && domain) g.domain = domain;
  g.members.push({ provider_id: r.provider_id, name: r.name || '', headline: r.headline || '' });
}

const all = [...groups.values()].filter(g => g.company || g.domain);
console.log(`Emailless leads grouped into ${all.length} companies; processing ${Math.min(all.length, MAX_COMPANIES_PER_RUN)}`);

return all.slice(0, MAX_COMPANIES_PER_RUN).map(g => ({ json: { ...g, known_emails: [...knownEmails] } }));

// Resolve a company domain and confirm it can receive mail.
// .org first - this pool is nonprofit/church/foundation heavy.

const g = $json;
const H = (typeof $helpers !== 'undefined' && $helpers) ? $helpers : this.helpers;
const hasMx = async (domain) => {
  try {
    const dns = await H.httpRequest({ method: 'GET', url: `https://dns.google/resolve?name=${domain}&type=MX`, json: true });
    return !!(dns.Answer && dns.Answer.length > 0);
  } catch (e) { return false; }
};

if (g.domain) {
  const ok = await hasMx(g.domain);
  return { json: { ...g, domain_verified: ok, company_domain_source: ok ? 'lead_pool' : 'unverified' } };
}

const cleaned = String(g.company || '')
  .replace(/\b(inc|llc|corp|corporation|foundation|nonprofit|non-profit|ltd|co|the)\.?\b/gi, '')
  .replace(/[^\w\s]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

if (!cleaned) return { json: { ...g, domain: '', domain_verified: false, company_domain_source: '' } };

const words = cleaned.split(/\s+/).filter(Boolean);
const noSpaces = words.join('');
const firstTwo = words.slice(0, 2).join('') || words[0] || '';
const acronym = words.length >= 2 ? words.map(w => w[0]).join('') : '';

const candidates = [...new Set([
  `${noSpaces}.org`,
  `${firstTwo}.org`,
  acronym ? `${acronym}.org` : '',
  `${noSpaces}.com`,
  `${firstTwo}.com`,
  `${noSpaces}.net`
])].filter(d => d && d.length > 5);

for (const cand of candidates) {
  if (await hasMx(cand)) {
    return { json: { ...g, domain: cand, domain_verified: true, company_domain_source: 'mx_guess' } };
  }
}

return { json: { ...g, domain: '', domain_verified: false, company_domain_source: '' } };

const out = [];
for (const item of $input.all()) {
  for (const m of (item.json.members || [])) {
    out.push({ json: { provider_id: m.provider_id, enriched_status: 'domain_not_found', enriched_at: new Date().toISOString() } });
  }
}
return out;

const company = $('Loop Over Companies').item.json;
const resp = $json || {};

return { json: {
  job_id: resp.job_id || '',
  attempt: 0,
  status: resp.status || 'queued',
  start_failed: !resp.job_id,
  company: company.company,
  domain: company.domain,
  members: company.members || [],
  known_emails: company.known_emails || []
}};

// Hard ceiling of 20 attempts (~5 min) so a stuck job can never spin forever.

const MAX_ATTEMPTS = 20;
const prev = $('Wait For Job').item.json;
const resp = $json || {};

const attempt = (prev.attempt || 0) + 1;
const status = String(resp.status || '').toLowerCase();
const finished = status === 'completed' || status === 'failed';
const exhausted = attempt >= MAX_ATTEMPTS;

return { json: {
  job_id: prev.job_id,
  attempt: attempt,
  status: status || 'unknown',
  done: finished || exhausted || prev.start_failed === true,
  timed_out: !finished && exhausted,
  start_failed: prev.start_failed === true,
  result: resp.result || null,
  company: prev.company,
  domain: prev.domain,
  members: prev.members || [],
  known_emails: prev.known_emails || []
}};

// Match discovered people back onto known leads, and collect anyone new.
// leads[] = SMTP-verified (currently always empty). unverified[] = pattern-built.
// We read both; the pre-filter and bounce handler rule on deliverability.

const APPEND_NEW_CONTACTS = true;

const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z\s]/g, ' ').replace(/\s+/g, ' ').trim();

// Strip honorifics/prefixes that corrupt matching (e.g. 'BCC Marvina D. Jackson').
const NOISE = new Set(['mr','mrs','ms','miss','dr','rev','pastor','bcc','the','jr','sr','ii','iii']);
const nameKey = (s) => norm(s)
  .split(' ')
  .filter(w => w.length > 1 && !NOISE.has(w))
  .filter((w, i, arr) => i === 0 || i === arr.length - 1)
  .join(' ');

const out = [];
let matched = 0, appended = 0, discovered = 0;

for (const item of $input.all()) {
  const j = item.json;
  const now = new Date().toISOString();
  const members = j.members || [];
  const knownEmails = new Set((j.known_emails || []).map(e => String(e).toLowerCase()));

  if (j.start_failed || j.timed_out || j.status === 'failed' || !j.result) {
    for (const m of members) {
      out.push({ json: { provider_id: m.provider_id, enriched_status: j.timed_out ? 'osint_timeout' : 'osint_failed', enriched_at: now } });
    }
    continue;
  }

  const res = j.result || {};
  const found = [
    ...(Array.isArray(res.leads) ? res.leads.map(l => ({ ...l, from_verified: true })) : []),
    ...(Array.isArray(res.unverified) ? res.unverified.map(l => ({ ...l, from_verified: false })) : [])
  ].filter(l => l && l.email);
  discovered += found.length;

  const claimed = new Set();

  for (const m of members) {
    const key = nameKey(m.name);
    if (!key) {
      out.push({ json: { provider_id: m.provider_id, enriched_status: 'no_name_to_match', enriched_at: now } });
      continue;
    }
    const hit = found.find(f => nameKey(f.name) === key && !claimed.has(f.email));
    if (hit) {
      claimed.add(hit.email);
      matched++;
      out.push({ json: {
        provider_id: m.provider_id,
        company_domain: j.domain,
        email: hit.email,
        email_source: hit.from_verified ? 'osint_verified' : 'osint_pattern',
        email_verified: false,
        sendability: '',
        email_check_result: '',
        enriched_status: 'osint_matched',
        enriched_at: now
      }});
    } else {
      out.push({ json: { provider_id: m.provider_id, company_domain: j.domain, enriched_status: 'osint_no_match', enriched_at: now } });
    }
  }

  if (APPEND_NEW_CONTACTS) {
    for (const f of found) {
      const email = String(f.email).toLowerCase();
      if (claimed.has(f.email) || knownEmails.has(email)) continue;
      knownEmails.add(email);
      appended++;
      out.push({ json: {
        provider_id: 'osint_' + Buffer.from(email).toString('base64').replace(/[^a-zA-Z0-9]/g, '').slice(0, 24),
        name: f.name || '',
        headline: f.title || '',
        linkedin_link: f.linkedin_url || '',
        company_name: j.company || '',
        company_domain: j.domain,
        email: f.email,
        email_source: f.from_verified ? 'osint_verified' : 'osint_pattern',
        email_verified: false,
        sendability: '',
        email_check_result: '',
        lead_source: 'osint_discovery',
        status: 'New',
        discovered_at: now,
        enriched_status: 'osint_new_contact',
        enriched_at: now
      }});
    }
  }
}

console.log(`OSINT: ${discovered} discovered, ${matched} matched, ${appended} appended`);
return out;

let rows = [];
try { rows = $('Match Leads To Rows').all().map(i => i.json); } catch (e) {}

const tally = {};
for (const r of rows) {
  const k = r.enriched_status || 'unknown';
  tally[k] = (tally[k] || 0) + 1;
}

return [{ json: { run_id: $execution.id, finished_at: new Date().toISOString(), rows_written: rows.length, emails_found: rows.filter(r => r.email).length, by_status: tally }}];
